<?php
/** Proof — JSON mode (spec "Proof", 6): every handler under a signed action token answers {ok, did, record_id, location}; the Clerk's run token pulls and allocates (no pause), drafts a charge, runs a schedule, saves a rule (source agent, the run, recorded_by the agent); the agent's refusals in the right words; usage_charge_approve by an agent answers 200 here — on the MCP path the kernel's hook pauses it as `other`. */
require __DIR__ . '/lib.php';
[$acme, $beta] = usage_world();
$marcoTok = ['X-Action-Token: ' . person_token(27)];
$priyaTok = ['X-Action-Token: ' . person_token(26)];
$beaTok = ['X-Action-Token: ' . person_token(28)];
$first = (string) one("SELECT to_char(date_trunc('month', current_date) - interval '1 month', 'YYYY-MM-DD')");

echo "1. A person's action token\n";
[$c, $b] = act_token('/usage/save.php', ['engagement' => $acme, 'kind' => 'hosting', 'description' => 'SMOKE by token', 'period_start' => '2026-09-01', 'period_end' => '2026-09-30', 'unit_cost' => '120', 'pricing' => 'markup', 'markup_pct' => '10'], $marcoTok);
$u = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $b['ok'] === true && $u > 0 && $b['refresh'] === 'usageChanged' && $b['status'] === 'draft' && $b['billable_amount'] === '132.00' && $b['cost_amount'] === '120.00' && isset($b['number'], $b['location'], $b['did']), 'usage_charge_draft: {ok, did, record_id, location, number, status, billable_amount, refresh}');
[$c, $b] = act_token('/usage/save.php', ['engagement' => $acme, 'kind' => 'magic', 'unit' => 'bushels'], $marcoTok);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && isset($b['error']['fields']['kind'], $b['error']['fields']['unit'], $b['error']['fields']['description'], $b['error']['fields']['period_start']), 'a refusal: 422 {error: {code: invalid, fields}}');
[$c, $b] = act_token('/usage/approve.php', ['charge' => $u], $marcoTok);
ok($c === 200 && $b['status'] === 'approved' && $b['billable_amount'] === '132.00' && isset($b['new_ai_alerts']), 'usage_charge_approve answers the status and the billable amount');
[$c, $b] = act_token('/usage/void.php', ['charge' => $u, 'reason' => 'SMOKE token void'], $marcoTok);
ok($c === 200 && $b['status'] === 'void', 'usage_charge_void');
[$c, $b] = act_token('/usage/void.php', ['charge' => $u], $marcoTok);
ok($c === 422 && isset($b['error']['fields']['reason']), 'a void without a reason: 422 with the field reason');
[$c, $b] = act_token('/usage/save.php', ['engagement' => $acme, 'kind' => 'hosting', 'description' => 'SMOKE to remove', 'period_start' => '2026-09-01', 'period_end' => '2026-09-30', 'unit_cost' => '1'], $marcoTok);
[$c2, $b2] = act_token('/usage/delete.php', ['charge' => (int) $b['record_id']], $marcoTok);
ok($c2 === 200 && $b2['ok'] === true && (int) one('SELECT count(*) FROM usage_charges WHERE id = :u', ['u' => (int) $b['record_id']]) === 0, 'usage_charge_delete');
[$c, $b] = act_token('/usage/approve.php', ['charge' => $u], $priyaTok);
ok($c === 403, 'Priya\'s token may not approve: 403');
// the import and the files, as multipart under the token
$csv = sys_get_temp_dir() . '/ct-json-' . bin2hex(random_bytes(3)) . '.csv';
file_put_contents($csv, "usage_date_utc,model,total_tokens,cost_usd\n2026-07-01,claude-sonnet,1000000,3.00\n2026-07-02,claude-sonnet,1000000,3.00\n");
$ch = curl_init(BASE . '/usage/import.php');
curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => array_merge(JSONH, $marcoTok), CURLOPT_POSTFIELDS => ['provider' => provider('anthropic'), 'engagement' => $acme, 'file' => new CURLFile($csv, 'text/csv', 'token.csv')]]);
$b = json_decode((string) curl_exec($ch), true);
ok(curl_getinfo($ch, CURLINFO_HTTP_CODE) === 200 && $b['ok'] === true && $b['inserted'] === 2 && $b['skipped'] === 0 && isset($b['import_id'], $b['location']), 'usage_import (multipart file, the provider\'s mapping): {ok, import_id, inserted, skipped, charge_ids}');
$imp = (int) $b['import_id'];
[$c, $b] = act_token('/usage/import-delete.php', ['import' => $imp], $marcoTok);
ok($c === 200 && $b['removed'] === 2, 'usage_import_delete answers how many it removed');
[$c, $b] = act_token('/settings/allocation-rules/save.php', ['name' => 'SMOKE token rule', 'engagement' => $acme, 'agent' => 801, 'share_pct' => '25', 'valid_from' => '2026-01-01'], $marcoTok);
$rule = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $b['ok'] === true && $rule > 0, 'allocation_rule_save: {ok, record_id, rule_id}');
[$c, $b] = act_token('/settings/allocation-rules/save.php', ['rule' => $rule, 'share_pct' => '30', '_partial' => '1'], $marcoTok);
ok($c === 200 && one('SELECT share_pct FROM allocation_rules WHERE id = :r', ['r' => $rule]) === '30.00', 'a rule changed by key alone keeps its other fields');
[$c, $b] = act_token('/settings/allocation-rules/delete.php', ['rule' => $rule], $marcoTok);
ok($c === 200 && $b['ok'] === true, 'allocation_rule_delete');
[$c, $b] = act_token('/settings/schedules/save.php', ['engagement' => $acme, 'kind' => 'hosting', 'description' => 'SMOKE token schedule', 'unit_cost' => '10', 'next_date' => $first], $marcoTok);
$sch = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $sch > 0 && $b['schedule_id'] === $sch, 'recurring_charge_save: {ok, record_id, schedule_id}');
[$c, $b] = act_token('/settings/schedules/run.php', ['schedule' => $sch], $marcoTok);
ok($c === 200 && $b['usage_charge_id'] > 0 && isset($b['next_date'], $b['number']), 'recurring_charge_run: {ok, usage_charge_id, number, next_date}');
[$c, $b] = act_token('/settings/schedules/delete.php', ['schedule' => $sch], $marcoTok);
ok($c === 200 && $b['ok'] === true, 'recurring_charge_delete');
$jdocs = ['2026-06' => ledger_doc('2026-06', 'closed', [ledger_line('anthropic', 777, 'JSON agent', 9, 'JSON dept', '20.0000')])];     // this proof's own month and agent: the other proofs' rules do not touch them
set_ledger($jdocs);
[$c, $b] = act_token('/usage/os/pull.php', [], $marcoTok);
ok($c === 200 && count($b['months']) === 1 && $b['months'][0]['period'] === '2026-06' && $b['months'][0]['new'] === true, 'ai_statement_pull: {ok, months[]}');
$rr = (int) ((act_token('/settings/allocation-rules/save.php', ['name' => 'SMOKE json rule', 'engagement' => $acme, 'agent' => 777, 'valid_from' => '2026-01-01', 'share_pct' => '100'], $marcoTok)[1]['record_id']) ?? 0);
[$c, $b] = act_token('/usage/os/allocate.php', ['period' => '2026-06'], $marcoTok);
ok($c === 200 && $b['charges'] === 1 && $b['allocated_amount'] === '20.00' && $b['remainder'] === '0.00' && $b['period'] === '2026-06' && $b['currency'] === 'USD' && count($b['summary']) === 1, 'ai_statement_allocate: {ok, charges, kept, allocated_amount, remainder, currency, summary[]}');
[$c, $b] = act_token('/usage/os/pull.php', ['period' => '2026-06'], $marcoTok);
ok($c === 200, 'pull by name');
[$sc, $body] = [req('GET', '/usage/os?period=2026-06', ['headers' => array_merge(JSONH, $marcoTok)])['code'], null];
ok($sc === 200, 'the screens answer JSON under the token too');
[$c, $b] = act_token('/usage/os/pull.php', [], $priyaTok);
ok($c === 403, 'Priya\'s token may not pull: 403');
kernel_state(function ($s) { $s['ledger']['mode'] = 'down'; return $s; });
[$c, $b] = act_token('/usage/os/pull.php', ['period' => '2026-09'], $marcoTok);
ok($c === 503 && ($b['error']['code'] ?? '') === 'unavailable', 'the kernel down: 503 {error: {code: unavailable, message}}');
clear_ledger();

echo "2. The Clerk's run token (a Billing agent)\n";
[$tok, $relay] = run_token(40, 882);
kernel_state(function ($s) { $s['facts']['882'] = ['valid' => true, 'is_agent' => true, 'member_id' => 40, 'run_id' => 882, 'request_id' => 'req-882', 'trigger' => 'duty', 'endpoints' => [['name' => 'Records MCP']]]; return $s; });
$h = ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay];
$jdocs['2026-05'] = ledger_doc('2026-05', 'closed', [ledger_line('anthropic', 777, 'JSON agent', 9, 'JSON dept', '8.0000')]);
set_ledger($jdocs);
$since = last_activity_id();
[$c, $b] = act_token('/usage/os/pull.php', ['period' => '2026-05'], $h);
ok($c === 200 && $b['ok'] === true, 'the Clerk pulls a month (no pause: a draft-free read)');
$log = activity('ai_statement.pull', $since);
ok(count($log) === 1 && $log[0]['source'] === 'agent' && (int) $log[0]['agent_run_id'] === 882 && (int) $log[0]['actor_member_id'] === 40, 'its row: source agent, run 882, actor the Clerk');
[$c, $b] = act_token('/usage/os/allocate.php', ['period' => '2026-05'], $h);
ok($c === 200 && $b['charges'] === 1 && activity('ai_statement.allocate', $since)[0]['source'] === 'agent', 'the Clerk allocates the month (drafts): charges made, the row is the agent\'s');
[$c, $b] = act_token('/usage/save.php', ['engagement' => $acme, 'kind' => 'hosting', 'description' => 'SMOKE Clerk drafts', 'period_start' => '2026-09-01', 'period_end' => '2026-09-30', 'unit_cost' => '25'], $h);
$cu = (int) ($b['record_id'] ?? 0);
$log = activity('usage_charge.draft', $since);
ok($c === 200 && $cu > 0 && $log[count($log) - 1]['source'] === 'agent' && (int) $log[count($log) - 1]['agent_run_id'] === 882 && json_decode((string) $log[count($log) - 1]['after'], true)['recorded_by'] === 40, 'the Clerk drafts a charge: source agent, run 882, recorded_by the Clerk');
[$c, $b] = act_token('/settings/schedules/save.php', ['engagement' => $acme, 'kind' => 'hosting', 'description' => 'SMOKE Clerk schedule', 'unit_cost' => '5', 'next_date' => $first], $h);
$cs = (int) $b['record_id'];
[$c, $b] = act_token('/settings/schedules/run.php', ['schedule' => $cs], $h);
ok($c === 200 && $b['usage_charge_id'] > 0 && activity('recurring_charge.run', $since)[0]['source'] === 'agent', 'the Clerk runs a due schedule');
[$c, $b] = act_token('/usage/approve.php', ['charge' => $cu], $h);
ok($c === 200 && $b['status'] === 'approved', 'usage_charge_approve by an agent: 200 here — on the MCP path the kernel\'s hook pauses it as `other` and never reaches this handler until a person approves (Phase 4)');
[$c, $b] = act_token('/usage/import-delete.php', ['import' => 999999], $h);
ok($c === 404, 'an import that is not there: 404');
clear_ledger();
kernel_state(function ($s) { unset($s['facts']); return $s; });
finish();
